<?php require_once __DIR__.'/include/db.php'; session_start(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$m=trim($_POST['mobile']??'');$text=trim($_POST['message']??'');$stmt=mysqli_prepare($conn,'INSERT INTO contact_messages(name,email,mobile,message) VALUES(?,?,?,?)');mysqli_stmt_bind_param($stmt,'ssss',$n,$e,$m,$text);$msg=mysqli_stmt_execute($stmt)?'Message successfully submit ho gaya.':'Message submit nahi hua.';} ?><!doctype html><html><head><meta charset="utf-8"><title>Contact - Mewar</title><style>body{font-family:Arial;background:#f4f7ff}.box{max-width:600px;margin:50px auto;background:#fff;padding:30px;border-radius:15px}input,textarea{width:100%;box-sizing:border-box;padding:12px;margin:8px 0 15px}button{padding:12px 25px;background:blue;color:#fff;border:0}</style></head><body><div class="box"><h1>Contact / Inquiry</h1><?php if($msg):?><p><?=htmlspecialchars($msg)?></p><?php endif;?><form method="post"><input name="name" placeholder="Name" required><input type="email" name="email" placeholder="Email" required><input name="mobile" placeholder="Mobile"><textarea name="message" rows="6" placeholder="Your message" required></textarea><button>Submit</button></form><p><a href="index.php">← Home</a></p></div></body></html>
